        heading: '長い管を折り返した構造',
        body: '実際の管長は2.5メートルほどあり、それを折り返してこの大きさに収めています。この構造のため運指が複雑で、同じ音を出す運指が複数ある場合もあります。速いパッセージでは、どの運指を選ぶかが演奏可能かどうかを左右します。',
