        heading: '音程を持つ打楽器',
        body: '大半の打楽器が明確な音高を持たないのに対し、ティンパニは調律されます。古典派では主音と属音に合わせた2台が標準で、和声の土台を打楽器で補強する役割を担いました。ペダルで音高を変えられるようになると、旋律的な扱いも可能になり、現代では複数台を用いるのが一般的です。',
