        heading: '現在の一般的な扱い',
        body: '現代では Andante よりやや速いと解釈するのが一般的です。ただし作曲家によっては逆の意味で使っている可能性もあるため、前後の楽章との関係や曲想から判断する必要があります。同じ作曲家が Andante と Andantino を両方使っている作品があれば、その比較が最も確実な手がかりになります。',
