        heading: '回る順序',
        body: '標準的なターンは、上の音・主音・下の音・主音の順に4音を演奏します。記号が上下反転している場合は、下の音から始めます。記号が音符の真上にあれば主音の発音と同時に回りはじめ、音符と次の音符のあいだにあれば、主音を鳴らしてからその後半で回ります。この位置の違いを見落とすと、リズムが変わってしまいます。',
