        heading: '終止を引き延ばす場所',
        body: 'カデンツァは、楽章の終わりに向かう終止形の途中で音楽を一度止め、独奏者が自由に演奏する部分です。和声的には、主和音の第二転回形の上で待機している状態が続き、カデンツァが終わると属和音から主和音へ進んで楽章が閉じます。つまりカデンツァは、一つの終止が長く引き延ばされた中に置かれた別世界です。',
