        heading: '主音は「帰る場所」',
        body: '主音が中心として機能するのは、他の音がそこへ向かう力を持っているからです。とくに導音（第7音）は半音下から主音へ強く引き寄せられ、属音（第5音）は和音として主音を指し示します。旋律が主音に着地したとき聴き手が安心するのは、この引力が解消されるためです。楽曲分析では、いつ主音から離れ、いつ戻るのかを追うことが、構造を理解する近道になります。',
