        heading: '平行調は内側に並ぶ',
        body: '五度圏の図では、外側に長調、内側に平行短調が書かれるのが一般的です。ハ長調の内側にはイ短調があり、両者は調号を共有します。同じ調号でも長調と短調で性格がまったく異なるため、楽譜を読むときは調号だけでなく、曲がどちらに着地しているかを必ず確認する必要があります。',
